    { id = 104967, tree = 1, row = 3, col = 2, ranks = 5, name = "Ferocity", icon = 134297, desc = { "Increases the critical strike chance of your pets and hawks by 2%.", "Increases the critical strike chance of your pets and hawks by 4%.", "Increases the critical strike chance of your pets and hawks by 6%.", "Increases the critical strike chance of your pets and hawks by 8%.", "Increases the critical strike chance of your pets and hawks by 10%." }, note = "+10% crit for pets and hawks. A pet doesn't crit without it (none in 217 swings in a combat log), and Frenzy needs its crits." },
    { id = 104966, tree = 1, row = 3, col = 3, ranks = 1, name = "Summon Hawk", icon = 132158, desc = { "Command a hawk to dive-bomb your targeted enemy, dealing (32 + 5% of Ranged Attack Power) Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot." }, note = "Hawks dive-bomb your target for 18 sec (two at once). Their damage isn't in the game files, so it's left out of the numbers." },
    { id = 104965, tree = 1, row = 4, col = 0, ranks = 2, name = "Spirit Bond", icon = 132121, desc = { "While your pet is active, you and your pet will regenerate 1% of total health every 10 sec.", "While your pet is active, you and your pet will regenerate 1% of total health every 5 sec." }, note = "You and your pet regenerate 1% health every 5 sec: less downtime while leveling." },
    { id = 104964, tree = 1, row = 4, col = 1, ranks = 1, name = "Intimidation", icon = 132111, requires = { 104970, 1 }, desc = { "Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat." } },
    { id = 104963, tree = 1, row = 4, col = 3, ranks = 2, name = "Bestial Discipline", icon = 136006, desc = { "Increases the Focus regeneration of your pets by 10% and allows 25% of your Mana regeneration to continue while casting.", "Increases the Focus regeneration of your pets by 20% and allows 50% of your Mana regeneration to continue while casting." } },
    { id = 104962, tree = 1, row = 5, col = 2, ranks = 5, name = "Frenzy", icon = 134296, requires = { 104967, 5 }, desc = { "Gives your pet a 20% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 40% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 60% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 80% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.", "Gives your pet a 100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike." }, note = "Your pet gets +30% attack speed for 8 sec after a crit. It does nothing without Ferocity: a pet doesn't crit otherwise." },
    { id = 104961, tree = 1, row = 6, col = 1, ranks = 1, name = "Bestial Wrath", icon = 132127, requires = { 104964, 1 }, desc = { "Send your pet into a rage causing 50% additional damage for 18 sec.  While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed." } },
    { id = 105013, tree = 2, row = 0, col = 0, ranks = 3, name = "Hawk Eye", icon = 132327, desc = { "Increases the range of your ranged weapons by 2 yards.", "Increases the range of your ranged weapons by 4 yards.", "Increases the range of your ranged weapons by 6 yards." } },
    { id = 105012, tree = 2, row = 0, col = 1, ranks = 5, name = "Improved Concussive Shot", icon = 135860, desc = { "Gives your Concussive Shot a 4% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 8% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 12% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 16% chance to stun the target for 3 sec.", "Gives your Concussive Shot a 20% chance to stun the target for 3 sec." } },
    { id = 105011, tree = 2, row = 0, col = 2, ranks = 5, name = "Lethal Attacks", icon = 132312, desc = { "Increases your critical strike chance with all attacks by 1%.", "Increases your critical strike chance with all attacks by 2%.", "Increases your critical strike chance with all attacks by 3%.", "Increases your critical strike chance with all attacks by 4%.", "Increases your critical strike chance with all attacks by 5%." } },
    { id = 110870, tree = 2, row = 1, col = 0, ranks = 3, name = "Improved Stings", icon = 132204, desc = { "Increases the damage of your Serpent Sting ability by 6%, reduces the cooldown of your Viper Sting ability by 2 sec, and increases the duration of your Scorpid Sting ability by 15 sec.", "Increases the damage of your Serpent Sting ability by 13%, reduces the cooldown of your Viper Sting ability by 4 sec, and increases the duration of your Scorpid Sting ability by 30 sec.", "Increases the damage of your Serpent Sting ability by 20%, reduces the cooldown of your Viper Sting ability by 6 sec, and increases the duration of your Scorpid Sting ability by 45 sec." } },
    { id = 105009, tree = 2, row = 1, col = 1, ranks = 5, name = "Efficiency", icon = 135865, desc = { "Reduces the Mana cost of your Shots, Stings, and melee abilities by 3%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 6%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 9%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 12%.", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 15%." }, note = "Shots, stings and melee abilities cost 15% less mana. Hunters run out of mana in long fights; this keeps the shots going." },
    { id = 105008, tree = 2, row = 1, col = 2, ranks = 5, name = "Careful Aim", icon = 132217, desc = { "Increases your Attack Power by 20% of your Intellect.", "Increases your Attack Power by 40% of your Intellect.", "Increases your Attack Power by 60% of your Intellect.", "Increases your Attack Power by 80% of your Intellect.", "Increases your Attack Power by 100% of your Intellect." } },
    { id = 105005, tree = 2, row = 2, col = 0, ranks = 2, name = "Rapid Killing", icon = 132205, desc = { "Reduces the cooldown on your Rapid Fire ability by 1 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 10%.", "Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." } },
    { id = 105006, tree = 2, row = 2, col = 1, ranks = 5, name = "Improved Arcane Shot", icon = 132218, desc = { "Reduces the cooldown of your Arcane Shot by 0.3 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 0.6 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 0.9 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 1.2 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.", "Reduces the cooldown of your Arcane Shot by 1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot." }, note = "Arcane Shot's cooldown drops by 1.5 sec, so you fit more of them between Auto Shots." },
    { id = 105007, tree = 2, row = 2, col = 3, ranks = 1, name = "Lone Wolf", icon = 132266, desc = { "You deal 20% increased damage with all attacks while you do not have an active pet." } },
    { id = 105004, tree = 2, row = 3, col = 1, ranks = 1, name = "Trueshot Aura", icon = 132329, desc = { "Increases the Ranged Attack Power of party or raid members within 45 yds by 20." } },
    { id = 105002, tree = 2, row = 3, col = 2, ranks = 5, name = "Mortal Shots", icon = 132271, requires = { 105008, 5 }, desc = { "Increases the critical strike damage bonus on all ranged abilities by 6%.", "Increases the critical strike damage bonus on all ranged abilities by 12%.", "Increases the critical strike damage bonus on all ranged abilities by 18%.", "Increases the critical strike damage bonus on all ranged abilities by 24%.", "Increases the critical strike damage bonus on all ranged abilities by 30%." } },
    { id = 104999, tree = 2, row = 4, col = 0, ranks = 2, name = "Rapid Recuperation", icon = 236201, requires = { 105005, 2 }, desc = { "Afflicting a target with Serpent Sting allows 25% of your Mana Regeneration to continue while casting for 15 sec, increased to 50% when Rapid Killing is consumed.", "Afflicting a target with Serpent Sting allows 50% of your Mana Regeneration to continue while casting for 15 sec, increased to 100% when Rapid Killing is consumed." } },
    { id = 105001, tree = 2, row = 4, col = 2, ranks = 3, name = "Barrage", icon = 132330, desc = { "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 5%.", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 10%.", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 15%." } },
    { id = 105000, tree = 2, row = 4, col = 3, ranks = 1, name = "Scatter Shot", icon = 132153, desc = { "A short-range shot that deals 50% weapon damage and disorients the target for 4 sec.  Any damage caused will remove the effect.  Turns off your attack when used." } },
    { id = 104998, tree = 2, row = 5, col = 2, ranks = 5, name = "Ranged Weapon Specialization", icon = 135615, desc = { "Increases the damage you deal with ranged weapons by 1%.", "Increases the damage you deal with ranged weapons by 2%.", "Increases the damage you deal with ranged weapons by 3%.", "Increases the damage you deal with ranged weapons by 4%.", "Increases the damage you deal with ranged weapons by 5%." } },
    { id = 104997, tree = 2, row = 6, col = 1, ranks = 1, name = "Sniper Shot", icon = 1412205, requires = { 105004, 1 }, desc = { "A long-range shot that deals ranged damage plus 320 and increases the range of your next 3 Shots by 10 yards for 10 sec." } },
    { id = 104996, tree = 3, row = 0, col = 1, ranks = 5, name = "Improved Tracking", icon = 134154, desc = { "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 1%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 2%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 3%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 4%.", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 5%." }, note = "+5% damage to whatever type you're tracking (Beasts, Humanoids, Undead...). Pick the boss's type and it's a flat damage boost; the planner doesn't know the target's type, so it can't count it." },
    { id = 104995, tree = 3, row = 0, col = 2, ranks = 5, name = "Deflection", icon = 132269, desc = { "Increases your Parry chance by 1%.", "Increases your Parry chance by 2%.", "Increases your Parry chance by 3%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 5%." } },
    { id = 104994, tree = 3, row = 1, col = 0, ranks = 5, name = "Entrapment", icon = 136100, desc = { "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 1 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 2 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 3 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 4 sec.", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 5 sec." } },
    { id = 104993, tree = 3, row = 1, col = 1, ranks = 2, name = "Savage Strikes", icon = 132277, desc = { "Increases the critical strike chance of all your melee abilities by 2%.", "Increases the critical strike chance of all your melee abilities by 4%." } },
    { id = 104992, tree = 3, row = 1, col = 2, ranks = 5, name = "Survivalist", icon = 136223, desc = { "Increases your total Health by 2%.", "Increases your total Health by 4%.", "Increases your total Health by 6%.", "Increases your total Health by 8%.", "Increases your total Health by 10%." }, note = "+10% health: fewer deaths to area damage and pulls that go wrong." },
    { id = 104990, tree = 3, row = 1, col = 3, ranks = 3, name = "Improved Wing Clip", icon = 132309, desc = { "Gives your Wing Clip ability a 7% chance to immobilize the target for 5 sec.", "Gives your Wing Clip ability a 13% chance to immobilize the target for 5 sec.", "Gives your Wing Clip ability a 20% chance to immobilize the target for 5 sec." } },
    { id = 104991, tree = 3, row = 2, col = 0, ranks = 2, name = "Clever Traps", icon = 136106, desc = { "Increases the duration of Freezing and Frost trap effects by 15% and the damage of Immolation and Explosive trap effects by 15%.", "Increases the duration of Freezing and Frost trap effects by 30% and the damage of Immolation and Explosive trap effects by 30%." }, note = "Immolation and Explosive Trap deal 30% more and Freezing/Frost Trap last 30% longer. In Forever traps work in combat, so a melee Survival Hunter keeps using them." },
    { id = 104987, tree = 3, row = 2, col = 1, ranks = 3, name = "Surefooted", icon = 132219, desc = { "Increases your hit chance by 1% and reduces the duration of movement impairing effects on you by 10%.", "Increases your hit chance by 2% and reduces the duration of movement impairing effects on you by 20%.", "Increases your hit chance by 3% and reduces the duration of movement impairing effects on you by 30%." }, note = "More hit (fewer misses) and shorter slows on you. Hit is worth the most until you reach the cap; see Hit on the panel." },
    { id = 104986, tree = 3, row = 2, col = 2, ranks = 1, name = "Deterrence", icon = 132369, desc = { "When activated, increases your Dodge and Parry chance by 25% for 10 sec." }, note = "+25% dodge and parry for 10 sec: the emergency button when something turns on you." },
    { id = 104988, tree = 3, row = 3, col = 0, ranks = 2, name = "Survival Tactics", icon = 132149, desc = { "Increases your chance to hit with your Trap and Feign Death abilities by 5%.", "Increases your chance to hit with your Trap and Feign Death abilities by 10%." } },
    { id = 110861, tree = 3, row = 3, col = 1, ranks = 5, name = "Predator's Edge", icon = 132147, desc = { "Increases your melee ability critical strike damage by 6% and your Off Hand weapon damage by 10%.", "Increases your melee ability critical strike damage by 12% and your Off Hand weapon damage by 20%.", "Increases your melee ability critical strike damage by 18% and your Off Hand weapon damage by 30%.", "Increases your melee ability critical strike damage by 24% and your Off Hand weapon damage by 40%.", "Increases your melee ability critical strike damage by 30% and your Off Hand weapon damage by 50%." } },
    { id = 104989, tree = 3, row = 3, col = 2, ranks = 1, name = "Counterattack", icon = 132336, requires = { 104986, 1 }, desc = { "A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 26 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried." }, note = "After you parry, a strike that also roots the target for 5 sec. Free damage and control in melee." },
    { id = 104983, tree = 3, row = 4, col = 0, ranks = 2, name = "Resourcefulness", icon = 132207, desc = { "Reduces the Mana cost of your Trap and melee abilities by 30%, and grants your melee and ranged ability Critical Strikes a 50% chance to allow 50% of your Mana Regeneration to continue while casting for 30 sec.", "Reduces the Mana cost of your Trap and melee abilities by 60%, and grants your melee and ranged ability Critical Strikes a 100% chance to allow 50% of your Mana Regeneration to continue while casting for 30 sec." } },
    { id = 104985, tree = 3, row = 4, col = 1, ranks = 2, name = "Expose Prey", icon = 132215, desc = { "Grants your melee and ranged attacks against enemies afflicted by Hunter's Mark a 5% chance to allow an activation of Mongoose Bite. Lasts 10 sec.", "Grants your melee and ranged attacks against enemies afflicted by Hunter's Mark a 10% chance to allow an activation of Mongoose Bite. Lasts 10 sec." } },
    { id = 110860, tree = 3, row = 4, col = 2, ranks = 2, name = "Survivalist's Discipline", icon = 132178, desc = { "Reduces the cooldown of your Trap and Deterrence abilities by 20%.", "Reduces the cooldown of your Trap and Deterrence abilities by 40%." } },
    { id = 104981, tree = 3, row = 4, col = 3, ranks = 1, name = "Strider Kick", icon = 132198, desc = { "A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec." } },
    { id = 110859, tree = 3, row = 5, col = 2, ranks = 5, name = "Lightning Reflexes", icon = 136047, desc = { "Increases your Agility by 3%.", "Increases your Agility by 6%.", "Increases your Agility by 9%.", "Increases your Agility by 12%.", "Increases your Agility by 15%." } },
    { id = 104984, tree = 3, row = 6, col = 1, ranks = 1, name = "Lacerating Strikes", icon = 132155, requires = { 104985, 2 }, desc = { "Your Mongoose Bite also causes the target to Bleed for damage equal to 40% of the damage done by Mongoose Bite over 21 sec" } },
