  MAGE = {
    trees = { "Arcane", "Fire", "Frost" },
    -- link order: node ID, tree (1-3), row and column (from 0), ranks, name, icon (file ID), requires = { node ID, rank }, desc = the tooltip at each rank, note = why it's worth taking
    { id = 105815, tree = 1, row = 0, col = 0, ranks = 2, name = "Wand Specialization", icon = 135463, desc = { "Increases your damage with Wands by 13%.", "Increases your damage with Wands by 25%." } },
    { id = 105813, tree = 1, row = 0, col = 1, ranks = 5, name = "Improved Channeling", icon = 136096, desc = { "Gives your Arcane Missiles spell a 20% chance and your Arcane Blast and Arcane Wrath spells a 14% chance to not lose casting time when you take damage.", "Gives your Arcane Missiles spell a 40% chance and your Arcane Blast and Arcane Wrath spells a 28% chance to not lose casting time when you take damage.", "Gives your Arcane Missiles spell a 60% chance and your Arcane Blast and Arcane Wrath spells a 42% chance to not lose casting time when you take damage.", "Gives your Arcane Missiles spell a 80% chance and your Arcane Blast and Arcane Wrath spells a 56% chance to not lose casting time when you take damage.", "Gives your Arcane Missiles spell a 100% chance and your Arcane Blast and Arcane Wrath spells a 70% chance to not lose casting time when you take damage." } },
    { id = 105802, tree = 1, row = 0, col = 2, ranks = 3, name = "Arcane Resilience", icon = 135733, desc = { "Increases your Armor by an amount equal to 25% of your Intellect.", "Increases your Armor by an amount equal to 50% of your Intellect.", "Increases your Armor by an amount equal to 75% of your Intellect." } },
    { id = 105812, tree = 1, row = 1, col = 0, ranks = 2, name = "Arcane Subtlety", icon = 135894, desc = { "Reduces your target's resistance to all your spells by 8 and reduces the threat caused by your Arcane spells by 15%.", "Reduces your target's resistance to all your spells by 15 and reduces the threat caused by your Arcane spells by 30%." } },
    { id = 105811, tree = 1, row = 1, col = 1, ranks = 2, name = "Magic Absorption", icon = 136011, desc = { "Increases all your resistances by 5 and causes all spells you fully resist to restore 1% of your total mana. Cannot trigger more often than 1 time per sec.", "Increases all your resistances by 10 and causes all spells you fully resist to restore 2% of your total mana. Cannot trigger more often than 1 time per sec." } },
    { id = 105810, tree = 1, row = 1, col = 2, ranks = 5, name = "Arcane Concentration", icon = 136170, desc = { "Gives you a 2% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 4% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 6% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 8% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%.", "Gives you a 10% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%." } },
    { id = 105809, tree = 1, row = 1, col = 3, ranks = 2, name = "Missile Barrage", icon = 236221, desc = { "Gives your Arcane Blast spell a 20% chance, and your Arcane Wrath, Fireball, Frostbolt, and Frostfire Bolt spells a 10% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec.", "Gives your Arcane Blast spell a 40% chance, and your Arcane Wrath, Fireball, Frostbolt, and Frostfire Bolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec." } },
    { id = 105808, tree = 1, row = 2, col = 0, ranks = 2, name = "Arcane Geometry", icon = 6035311, desc = { "Increases the range of your Arcane spells by 3 yards.", "Increases the range of your Arcane spells by 6 yards." } },
    { id = 105807, tree = 1, row = 2, col = 1, ranks = 3, name = "Arcane Impact", icon = 136116, desc = { "Increases the critical strike chance of your Arcane spells by 2%.", "Increases the critical strike chance of your Arcane spells by 4%.", "Increases the critical strike chance of your Arcane spells by 6%." } },
    { id = 105806, tree = 1, row = 2, col = 3, ranks = 1, name = "Arcane Blast", icon = 135735, desc = { "Blasts the target with energy, dealing 33 to 39 Arcane damage. Each time you cast Arcane Blast, you gain 12% of your Intellect as Spell Damage and the mana cost of Arcane Blast is increased by 100%. Effect stacks up to 4 times and lasts 18 sec from time of initial application." } },
    { id = 105805, tree = 1, row = 3, col = 0, ranks = 2, name = "Arcane Shielding", icon = 136153, desc = { "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 17% and increases the resistances granted by your Mage Armor spell by 25%.", "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 33% and increases the resistances granted by your Mage Armor spell by 50%." } },
    { id = 105804, tree = 1, row = 3, col = 1, ranks = 2, name = "Improved Counterspell", icon = 135856, desc = { "Your Counterspell also Silences the target for 2 sec.", "Your Counterspell also Silences the target for 4 sec." } },
    { id = 105803, tree = 1, row = 3, col = 2, ranks = 3, name = "Arcane Meditation", icon = 136208, requires = { 105810, 5 }, desc = { "Allows 17% of your Mana regeneration to continue while casting.", "Allows 33% of your Mana regeneration to continue while casting.", "Allows 50% of your Mana regeneration to continue while casting." } },
    { id = 113627, tree = 1, row = 3, col = 3, ranks = 1, name = "Arcane Wrath", icon = 236222, requires = { 105806, 1 }, desc = { "Launches a projectile of pure Arcane energy at the enemy target, causing 121 to 147 Arcane damage. This spell gains additional Spell Damage equal to 5% of your maximum Mana." } },
    { id = 105801, tree = 1, row = 4, col = 1, ranks = 1, name = "Presence of Mind", icon = 136031, desc = { "When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell." } },
    { id = 105800, tree = 1, row = 4, col = 2, ranks = 5, name = "Arcane Mind", icon = 136129, desc = { "Increases your Intellect by 2% and increases the critical strike damage bonus of your Arcane spells by 20%.", "Increases your Intellect by 4% and increases the critical strike damage bonus of your Arcane spells by 40%.", "Increases your Intellect by 6% and increases the critical strike damage bonus of your Arcane spells by 60%.", "Increases your Intellect by 8% and increases the critical strike damage bonus of your Arcane spells by 80%.", "Increases your Intellect by 10% and increases the critical strike damage bonus of your Arcane spells by 100%." } },
    { id = 105799, tree = 1, row = 5, col = 2, ranks = 3, name = "Arcane Instability", icon = 136222, desc = { "Increases the damage done by your spells by 1% and your critical strike chance by 1%.", "Increases the damage done by your spells by 2% and your critical strike chance by 2%.", "Increases the damage done by your spells by 3% and your critical strike chance by 3%." } },
    { id = 105798, tree = 1, row = 6, col = 1, ranks = 1, name = "Arcane Power", icon = 136048, requires = { 105801, 1 }, desc = { "For the next 15 sec, your spells deal 30% more damage while costing 30% more mana to cast." } },
    { id = 105796, tree = 2, row = 0, col = 1, ranks = 5, name = "Incineration", icon = 135813, desc = { "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 2%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 4%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 6%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 8%.", "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 10%." } },
