    { id = 110872, tree = 1, row = 4, col = 0, ranks = 2, name = "Consecrated Ground", icon = 135926, desc = { "Gives your Holy spells 5% increased damage against the first 4 enemies that enter your Consecration.", "Gives your Holy spells 10% increased damage against the first 4 enemies that enter your Consecration." } },
