    { id = 110879, tree = 2, row = 5, col = 2, ranks = 3, name = "Iron Creed", icon = 135925, desc = { "Increases the threat generated by your Holy Strike ability by 10%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 2% for 6 sec.", "Increases the threat generated by your Holy Strike ability by 20%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 4% for 6 sec.", "Increases the threat generated by your Holy Strike ability by 30%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 6% for 6 sec." } },
    { id = 110875, tree = 2, row = 6, col = 1, ranks = 1, name = "Shieldsworn", icon = 135911, requires = { 105628, 1 }, desc = { "Reduces the cooldown of your Holy Strike ability by 4 sec. Additionally, Holy Strike now strikes with your shield, triggering your active Holy Shield and Shield Specialization talents without consuming their charges or triggering their cooldowns, and allowing you to Block spells for 6 sec." } },
    { id = 105707, tree = 3, row = 0, col = 1, ranks = 5, name = "Deflection", icon = 132269, desc = { "Increases your Parry chance by 1%.", "Increases your Parry chance by 2%.", "Increases your Parry chance by 3%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 5%." } },
    { id = 105706, tree = 3, row = 0, col = 2, ranks = 5, name = "Benediction", icon = 135863, desc = { "Reduces the Mana cost of all instant cast spells and abilities by 2%.", "Reduces the Mana cost of all instant cast spells and abilities by 4%.", "Reduces the Mana cost of all instant cast spells and abilities by 6%.", "Reduces the Mana cost of all instant cast spells and abilities by 8%.", "Reduces the Mana cost of all instant cast spells and abilities by 10%." } },
