    { id = 105701, tree = 3, row = 1, col = 2, ranks = 3, name = "Sanctified Judgement", icon = 236255, desc = { "Gives your Judgement ability a 33% chance to return 20% of the Mana cost of the judged seal.", "Gives your Judgement ability a 66% chance to return 40% of the Mana cost of the judged seal.", "Gives your Judgement ability a 100% chance to return 60% of the Mana cost of the judged seal." } },
    { id = 105702, tree = 3, row = 2, col = 0, ranks = 3, name = "Vindication", icon = 135985, desc = { "Gives your damaging melee attacks a chance to reduce the target's Attack Power by 67 for 30 sec.", "Gives your damaging melee attacks a chance to reduce the target's Attack Power by 134 for 30 sec.", "Gives your damaging melee attacks a chance to reduce the target's Attack Power by 200 for 30 sec." } },
