    { id = 105696, tree = 3, row = 2, col = 2, ranks = 1, name = "Seal of Command", icon = 132347, desc = { "Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage.  Only one Seal can be active on the Paladin at any one time.  Lasts 30 sec.\013\010\013\010Unleashing this Seal's energy will judge an enemy, instantly causing 70.9 Holy damage, 136 to 148 if the target is stunned or incapacitated." } },
    { id = 105699, tree = 3, row = 2, col = 3, ranks = 2, name = "Pursuit of Justice", icon = 135937, desc = { "Increases movement speed and mounted movement speed by 8%.  This does not stack with other movement speed increasing effects.", "Increases movement speed and mounted movement speed by 15%.  This does not stack with other movement speed increasing effects." } },
    { id = 105698, tree = 3, row = 3, col = 0, ranks = 2, name = "Eye for an Eye", icon = 135904, desc = { "All critical strikes against you cause 5% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.", "All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health." } },
    { id = 105700, tree = 3, row = 3, col = 1, ranks = 1, name = "Sacred Arbiter", icon = 135278, desc = { "Increases the damage of your Holy Strike ability by 20% and causes it to refresh all Judgement effects on the target." } },
    { id = 105697, tree = 3, row = 3, col = 3, ranks = 3, name = "Two-Handed Weapon Specialization", icon = 133041, desc = { "Increases the Physical and Holy damage you deal by 2%, and reduces all threat you generate by 7% while a two-handed melee weapon is equipped.", "Increases the Physical and Holy damage you deal by 4%, and reduces all threat you generate by 14% while a two-handed melee weapon is equipped.", "Increases the Physical and Holy damage you deal by 6%, and reduces all threat you generate by 20% while a two-handed melee weapon is equipped." } },
    { id = 113629, tree = 3, row = 4, col = 0, ranks = 2, name = "Turn Evil", icon = 135983, desc = { "Reduces the cast time of your Turn Undead spell by 0.5 sec, its cooldown by 5 sec, and allows it to affect Demons.", "Reduces the cast time of your Turn Undead spell by 1 sec, its cooldown by 10 sec, and allows it to affect Demons." } },
    { id = 105694, tree = 3, row = 4, col = 1, ranks = 1, name = "Repentance", icon = 135942, desc = { "Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids." } },
    { id = 105693, tree = 3, row = 4, col = 2, ranks = 3, name = "Vengeance", icon = 132275, requires = { 105696, 1 }, desc = { "Increases your Physical and Holy damage dealt by 1% for 30 sec after landing a non-periodic critical strike.  Stacks up to 5 times.", "Increases your Physical and Holy damage dealt by 2% for 30 sec after landing a non-periodic critical strike.  Stacks up to 5 times.", "Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a non-periodic critical strike.  Stacks up to 5 times." } },
    { id = 110882, tree = 3, row = 5, col = 2, ranks = 5, name = "Champion of the Light", icon = 236251, desc = { "Increases your spell damage by up to 12% of your Intellect, and reduces the cast time of your Hammer of Wrath by 0.2 sec.", "Increases your spell damage by up to 24% of your Intellect, and reduces the cast time of your Hammer of Wrath by 0.4 sec.", "Increases your spell damage by up to 36% of your Intellect, and reduces the cast time of your Hammer of Wrath by 0.6 sec.", "Increases your spell damage by up to 48% of your Intellect, and reduces the cast time of your Hammer of Wrath by 0.8 sec.", "Increases your spell damage by up to 60% of your Intellect, and reduces the cast time of your Hammer of Wrath by 1 sec." } },
    { id = 105692, tree = 3, row = 6, col = 1, ranks = 1, name = "Unsealed Wrath", icon = 135878, requires = { 105694, 1 }, desc = { "Your melee attacks store a copy of your active Seal for 15 sec, stacking up to 3 times. Landing an attack with a different Seal consumes all stacks, giving the stored Seal its normal chance to activate once per stack." } },
