    { id = 105908, tree = 2, row = 0, col = 1, ranks = 3, name = "Improved Imp", icon = 136218, desc = { "Increases the damage of your Imp's Firebolt spell by 10% and the effect of its Fire Shield spell by 10%.", "Increases the damage of your Imp's Firebolt spell by 20% and the effect of its Fire Shield spell by 20%.", "Increases the damage of your Imp's Firebolt spell by 30% and the effect of its Fire Shield spell by 30%." } },
    { id = 105907, tree = 2, row = 0, col = 2, ranks = 5, name = "Demonic Embrace", icon = 136172, desc = { "Increases your total Stamina by 3%.", "Increases your total Stamina by 6%.", "Increases your total Stamina by 9%.", "Increases your total Stamina by 12%.", "Increases your total Stamina by 15%." } },
    { id = 105906, tree = 2, row = 0, col = 3, ranks = 5, name = "Unholy Power", icon = 136206, desc = { "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 2%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 4%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 6%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 8%.", "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 10%." } },
    { id = 105902, tree = 2, row = 1, col = 0, ranks = 2, name = "Demonic Aegis", icon = 136185, desc = { "Increases the effectiveness of your Demon Skin and Demon Armor spells by 15%.", "Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%." } },
    { id = 105904, tree = 2, row = 1, col = 1, ranks = 3, name = "Improved Voidwalker", icon = 136221, desc = { "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 10%.", "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 20%.", "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%." } },
    { id = 105903, tree = 2, row = 1, col = 2, ranks = 3, name = "Fel Vitality", icon = 136150, desc = { "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 5%, and increases your maximum Mana by 5%.", "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 10%, and increases your maximum Mana by 10%.", "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%." } },
    { id = 105899, tree = 2, row = 1, col = 3, ranks = 2, name = "Demonic Energies", icon = 237564, desc = { "You heal your pet for 8% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 50% of the Mana you gain.", "You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain." } },
    { id = 105901, tree = 2, row = 2, col = 0, ranks = 3, name = "Improved Sayaad", icon = 4352493, desc = { "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 10%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 10%.", "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 20%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 20%.", "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%." } },
    { id = 105900, tree = 2, row = 2, col = 1, ranks = 1, name = "Demonic Sacrifice", icon = 136184, desc = { "When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 2 hrs. The effect is canceled if any Demon is summoned.\013\010\013\010Imp: Increases your Shadow damage by 15%.\013\010\013\010Voidwalker: Restores 2% of your total Mana every 4 sec.\013\010\013\010Succubus/Incubus: Increases your Fire damage by 15%.\013\010\013\010Felhunter: Restores 3% of your total Health every 4 sec." } },
    { id = 105898, tree = 2, row = 2, col = 2, ranks = 2, name = "Master Summoner", icon = 136164, desc = { "Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 2 sec and the Mana cost by 20%.", "Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%." } },
    { id = 105897, tree = 2, row = 3, col = 0, ranks = 2, name = "Decimation", icon = 135808, desc = { "Reduces the cooldown of your Soul Fire spell by 45%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 3% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 20% and costs no Soul Shards.", "Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards." } },
    { id = 105895, tree = 2, row = 3, col = 2, ranks = 1, name = "Fel Domination", icon = 136082, requires = { 105898, 2 }, desc = { "Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%." } },
    { id = 105896, tree = 2, row = 3, col = 3, ranks = 3, name = "Demonic Brand", icon = 4226151, desc = { "Your Searing Pain generates 17% less threat and brands the target for 10 sec. Your pet's next 2 attacks against the target deal (65 + 7.8% of the higher of Fire and Shadow Spell Power) to (68 + 7.8% of the higher of Fire and Shadow Spell Power) Fire or Shadow damage based on the pet. If Shadow damage is dealt, it has high threat.", "Your Searing Pain generates 33% less threat and brands the target for 10 sec. Your pet's next 4 attacks against the target deal (65 + 7.8% of the higher of Fire and Shadow Spell Power) to (68 + 7.8% of the higher of Fire and Shadow Spell Power) Fire or Shadow damage based on the pet. If Shadow damage is dealt, it has high threat.", "Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target deal (65 + 7.8% of the higher of Fire and Shadow Spell Power) to (68 + 7.8% of the higher of Fire and Shadow Spell Power) Fire or Shadow damage based on the pet. If Shadow damage is dealt, it has high threat." } },
    { id = 105894, tree = 2, row = 4, col = 0, ranks = 3, name = "Improved Felhunter", icon = 136217, desc = { "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 10%, and reduces the cooldown of its Spell Lock by 2 sec.", "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 20%, and reduces the cooldown of its Spell Lock by 4 sec.", "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec." } },
    { id = 105892, tree = 2, row = 4, col = 1, ranks = 1, name = "Soul Link", icon = 136160, requires = { 105900, 1 }, desc = { "When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active." } },
    { id = 105893, tree = 2, row = 4, col = 2, ranks = 3, name = "Demonic Knowledge", icon = 136165, desc = { "Increases your spell damage and your Demon pet's spell damage by up to 33% of your level while you have a summoned Demon pet active.", "Increases your spell damage and your Demon pet's spell damage by up to 67% of your level while you have a summoned Demon pet active.", "Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." } },
    { id = 105891, tree = 2, row = 5, col = 2, ranks = 5, name = "Master Demonologist", icon = 136203, desc = { "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\013\010\013\010Imp - Increases Fire damage done by 2%.\013\010\013\010Voidwalker - Reduces Physical damage taken by 2%.\013\010\013\010Succubus/Incubus - Increases Shadow damage done by 2%.\013\010\013\010Felhunter - Reduces Magic damage taken by 2%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\013\010\013\010Imp - Increases Fire damage done by 4%.\013\010\013\010Voidwalker - Reduces Physical damage taken by 4%.\013\010\013\010Succubus/Incubus - Increases Shadow damage done by 4%.\013\010\013\010Felhunter - Reduces Magic damage taken by 4%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\013\010\013\010Imp - Increases Fire damage done by 6%.\013\010\013\010Voidwalker - Reduces Physical damage taken by 6%.\013\010\013\010Succubus/Incubus - Increases Shadow damage done by 6%.\013\010\013\010Felhunter - Reduces Magic damage taken by 6%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\013\010\013\010Imp - Increases Fire damage done by 8%.\013\010\013\010Voidwalker - Reduces Physical damage taken by 8%.\013\010\013\010Succubus/Incubus - Increases Shadow damage done by 8%.\013\010\013\010Felhunter - Reduces Magic damage taken by 8%.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\013\010\013\010Imp - Increases Fire damage done by 10%.\013\010\013\010Voidwalker - Reduces Physical damage taken by 10%.\013\010\013\010Succubus/Incubus - Increases Shadow damage done by 10%.\013\010\013\010Felhunter - Reduces Magic damage taken by 10%." } },
    { id = 105890, tree = 2, row = 6, col = 1, ranks = 1, name = "Demonic Pact", icon = 5927650, requires = { 105892, 1 }, desc = { "Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect." } },
    { id = 105881, tree = 3, row = 0, col = 0, ranks = 2, name = "Destructive Reach", icon = 136133, desc = { "Increases the range of your Destruction spells by 10%.", "Increases the range of your Destruction spells by 20%." } },
    { id = 105889, tree = 3, row = 0, col = 1, ranks = 5, name = "Improved Shadow Bolt", icon = 136197, desc = { "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 4% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 8% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 12% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 16% for 12 sec.", "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 20% for 12 sec." } },
    { id = 105888, tree = 3, row = 0, col = 2, ranks = 5, name = "Bane", icon = 136146, desc = { "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.1 sec and your Soul Fire spell by 0.4 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.2 sec and your Soul Fire spell by 0.8 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.3 sec and your Soul Fire spell by 1.2 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.4 sec and your Soul Fire spell by 1.6 sec.", "Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.5 sec and your Soul Fire spell by 2 sec." } },
    { id = 105885, tree = 3, row = 1, col = 0, ranks = 5, name = "Molten Skin", icon = 132221, desc = { "Reduces all damage taken by 2%.", "Reduces all damage taken by 4%.", "Reduces all damage taken by 6%.", "Reduces all damage taken by 8%.", "Reduces all damage taken by 10%." } },
    { id = 105887, tree = 3, row = 1, col = 1, ranks = 3, name = "Cataclysm", icon = 135831, desc = { "Reduces the Mana cost of your Destruction spells by 3%.", "Reduces the Mana cost of your Destruction spells by 6%.", "Reduces the Mana cost of your Destruction spells by 10%." } },
    { id = 105886, tree = 3, row = 1, col = 2, ranks = 5, name = "Aftermath", icon = 135805, desc = { "Increases the initial damage of your Immolate spell by 10% and your Conflagrate spell has a 20% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 20% and your Conflagrate spell has a 40% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 30% and your Conflagrate spell has a 60% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 40% and your Conflagrate spell has a 80% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.", "Increases the initial damage of your Immolate spell by 50% and your Conflagrate spell has a 100% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec." } },
    { id = 105883, tree = 3, row = 2, col = 1, ranks = 5, name = "Ruin", icon = 136207, desc = { "Increases the critical strike damage bonus of your Destruction spells by 20%.", "Increases the critical strike damage bonus of your Destruction spells by 40%.", "Increases the critical strike damage bonus of your Destruction spells by 60%.", "Increases the critical strike damage bonus of your Destruction spells by 80%.", "Increases the critical strike damage bonus of your Destruction spells by 100%." } },
    { id = 105884, tree = 3, row = 2, col = 2, ranks = 1, name = "Shadowburn", icon = 136191, desc = { "Instantly blasts the target for 65 to 74 Shadow damage.  If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard." } },
    { id = 105882, tree = 3, row = 3, col = 0, ranks = 3, name = "Intensity", icon = 135819, desc = { "Gives your Destruction spells a 23% chance to not lose casting time when you take damage.", "Gives your Destruction spells a 47% chance to not lose casting time when you take damage.", "Gives your Destruction spells a 70% chance to not lose casting time when you take damage." } },
    { id = 105879, tree = 3, row = 3, col = 1, ranks = 3, name = "Agonizing Flames", icon = 135827, desc = { "Increases the critical strike chance of your Searing Pain spell by 3% and the damage done by all your Destruction spells by 3%.", "Increases the critical strike chance of your Searing Pain spell by 7% and the damage done by all your Destruction spells by 7%.", "Increases the critical strike chance of your Searing Pain spell by 10% and the damage done by all your Destruction spells by 10%." } },
    { id = 105880, tree = 3, row = 3, col = 2, ranks = 1, name = "Conflagrate", icon = 135807, desc = { "Ignites a target that is already afflicted by your Immolate spell, dealing 87 to 112 Fire damage and consuming your Immolate effect." } },
    { id = 105878, tree = 3, row = 4, col = 0, ranks = 2, name = "Pyroclasm", icon = 135830, requires = { 105882, 3 }, desc = { "Gives your Soul Fire spell a 13% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 13% chance over their duration to Stun targets they damage for 3 sec.", "Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec." } },
    { id = 105876, tree = 3, row = 4, col = 1, ranks = 1, name = "Bane of Havoc", icon = 460695, desc = { "Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target." } },
    { id = 105877, tree = 3, row = 4, col = 2, ranks = 3, name = "Fire and Brimstone", icon = 135821, requires = { 105880, 1 }, desc = { "Increases the critical strike chance of your Conflagrate spell by 8%.", "Increases the critical strike chance of your Conflagrate spell by 17%.", "Increases the critical strike chance of your Conflagrate spell by 25%." } },
    { id = 105875, tree = 3, row = 5, col = 2, ranks = 5, name = "Shadow and Flame", icon = 135823, desc = { "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 4% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 4% for 20 sec. In addition, Conflagrate has a 20% chance not to consume Immolate, and Shadowburn has a 20% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 8% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 8% for 20 sec. In addition, Conflagrate has a 40% chance not to consume Immolate, and Shadowburn has a 40% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 12% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 12% for 20 sec. In addition, Conflagrate has a 60% chance not to consume Immolate, and Shadowburn has a 60% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 16% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 16% for 20 sec. In addition, Conflagrate has a 80% chance not to consume Immolate, and Shadowburn has a 80% chance to instantly refund a Soul Shard.", "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 20% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 20% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard." } },
    { id = 105874, tree = 3, row = 6, col = 1, ranks = 1, name = "Incinerate", icon = 135789, requires = { 105876, 1 }, desc = { "Deals 99 to 115 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate." } },
  },
  WARRIOR = {
    trees = { "Arms", "Fury", "Protection" },
    -- link order: node ID, tree (1-3), row and column (from 0), ranks, name, icon (file ID), requires = { node ID, rank }, desc = the tooltip at each rank, note = why it's worth taking
    { id = 105958, tree = 1, row = 0, col = 0, ranks = 3, name = "Improved Heroic Strike", icon = 132282, desc = { "Reduces the cost of your Heroic Strike ability by 1 Rage.", "Reduces the cost of your Heroic Strike ability by 2 Rage.", "Reduces the cost of your Heroic Strike ability by 3 Rage." }, note = "Heroic Strike costs 3 less rage. It's what every warrior presses with spare rage, so the saving adds up over a fight; it's also a cheap first row point." },
    { id = 105957, tree = 1, row = 0, col = 1, ranks = 5, name = "Deflection", icon = 132269, desc = { "Increases your Parry chance by 1%.", "Increases your Parry chance by 2%.", "Increases your Parry chance by 3%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 5%." }, note = "More parry: fewer hits land, and parries feed Master of Defense rage and Revenge." },
    { id = 105956, tree = 1, row = 0, col = 2, ranks = 3, name = "Improved Rend", icon = 132155, desc = { "Increases the Bleed damage done by your Rend ability by 12%.", "Increases the Bleed damage done by your Rend ability by 23%.", "Increases the Bleed damage done by your Rend ability by 35%." }, note = "Rend's bleed does 35% more. With Bloodthrill your main-hand hits on a Rended target can light up Overpower, so Rend is kept up anyway; this makes that upkeep pay for itself." },
    { id = 105955, tree = 1, row = 1, col = 0, ranks = 2, name = "Improved Charge", icon = 132337, desc = { "Increases the Rage generated by your Charge ability by 3.", "Increases the Rage generated by your Charge ability by 6." }, note = "Charge gives 6 more rage: you start every pull with an attack ready." },
    { id = 105954, tree = 1, row = 1, col = 1, ranks = 3, name = "Improved Tactical Mastery", icon = 136031, desc = { "Tactical Mastery lets you retain up to an additional 5 Rage when you change stances.", "Tactical Mastery lets you retain up to an additional 10 Rage when you change stances.", "Tactical Mastery lets you retain up to an additional 15 Rage when you change stances." }, note = "Keeps more of your rage when you change stance. Arms swaps to Battle Stance for Overpower and Berserker for Whirlwind; a tank swaps between Defensive and the others. Without it a swap throws most of your rage away." },
    { id = 105952, tree = 1, row = 1, col = 3, ranks = 2, name = "Improved Overpower", icon = 135275, desc = { "Increases the critical strike chance of your Overpower ability by 25%.", "Increases the critical strike chance of your Overpower ability by 50%." }, note = "+50% crit chance on Overpower: almost every Overpower crits, and each crit also feeds Deep Wounds and Impale." },
    { id = 105951, tree = 1, row = 2, col = 1, ranks = 1, name = "Anger Management", icon = 135881, requires = { 105954, 3 }, desc = { "Generates 1 Rage every 3 sec while in combat, and reduces Rage loss while out of combat by 30%." } },
    { id = 105950, tree = 1, row = 2, col = 2, ranks = 3, name = "Deep Wounds", icon = 132090, requires = { 105956, 3 }, desc = { "Your critical strikes cause your opponent to Bleed, dealing 20% of your melee weapon's average damage over 12 sec.", "Your critical strikes cause your opponent to Bleed, dealing 40% of your melee weapon's average damage over 12 sec.", "Your critical strikes cause your opponent to Bleed, dealing 60% of your melee weapon's average damage over 12 sec." } },
    { id = 105949, tree = 1, row = 3, col = 0, ranks = 1, name = "Spearing Strike", icon = 135124, desc = { "A brutal attack that deals 75% weapon damage. Deals an additional 75% weapon damage against Giants, Dragonkin, and mounted targets. Mounted targets are dismounted." } },
    { id = 105948, tree = 1, row = 3, col = 1, ranks = 3, name = "Two-Handed Weapon Specialization", icon = 132400, desc = { "Increases the damage you deal with two-handed melee weapons by 2%.", "Increases the damage you deal with two-handed melee weapons by 4%.", "Increases the damage you deal with two-handed melee weapons by 6%." } },
    { id = 105947, tree = 1, row = 3, col = 2, ranks = 2, name = "Impale", icon = 132312, requires = { 105950, 3 }, desc = { "Increases the critical strike damage bonus of your abilities by 10%.", "Increases the critical strike damage bonus of your abilities by 20%." } },
    { id = 110524, tree = 1, row = 4, col = 0, ranks = 2, name = "Bloodthrill", icon = 135271, desc = { "Grants your Main Hand melee attacks against enemies afflicted by your Rend a 10% chance to allow an activation of Overpower.", "Grants your Main Hand melee attacks against enemies afflicted by your Rend a 20% chance to allow an activation of Overpower." }, note = "Main-hand hits on a target with your Rend have a 20% chance to allow Overpower. Overpower is one of your cheapest, hardest-hitting attacks, and bosses rarely dodge, so this is how Arms gets to use it often." },
    { id = 105945, tree = 1, row = 4, col = 1, ranks = 1, name = "Sweeping Strikes", icon = 132306, desc = { "Your next 5 melee attacks strike an additional nearby opponent." }, note = "Your next hits also strike a second enemy. Strong on two-target fights and while leveling, and it's needed to reach Mortal Strike." },
    { id = 105944, tree = 1, row = 4, col = 2, ranks = 5, name = "Weaponmaster", icon = 1085608, desc = { "Gives your melee weapon attacks a benefit depending on the weapon.\013\010\013\010Axe/Polearm: Increases your\013\010critical strike chance by 1%.\013\010\013\010Mace/Staff: Your attacks ignore\013\0103% of your target's armor.\013\010\013\010Sword: Your successful melee \013\010attacks have a 1% chance to \013\010trigger an extra attack on the \013\010target.", "Gives your melee weapon attacks a benefit depending on the weapon.\013\010\013\010Axe/Polearm: Increases your\013\010critical strike chance by 2%.\013\010\013\010Mace/Staff: Your attacks ignore\013\0106% of your target's armor.\013\010\013\010Sword: Your successful melee \013\010attacks have a 2% chance to \013\010trigger an extra attack on the \013\010target.", "Gives your melee weapon attacks a benefit depending on the weapon.\013\010\013\010Axe/Polearm: Increases your\013\010critical strike chance by 3%.\013\010\013\010Mace/Staff: Your attacks ignore\013\0109% of your target's armor.\013\010\013\010Sword: Your successful melee \013\010attacks have a 3% chance to \013\010trigger an extra attack on the \013\010target.", "Gives your melee weapon attacks a benefit depending on the weapon.\013\010\013\010Axe/Polearm: Increases your\013\010critical strike chance by 4%.\013\010\013\010Mace/Staff: Your attacks ignore\013\01012% of your target's armor.\013\010\013\010Sword: Your successful melee \013\010attacks have a 4% chance to \013\010trigger an extra attack on the \013\010target.", "Gives your melee weapon attacks a benefit depending on the weapon.\013\010\013\010Axe/Polearm: Increases your\013\010critical strike chance by 5%.\013\010\013\010Mace/Staff: Your attacks ignore\013\01015% of your target's armor.\013\010\013\010Sword: Your successful melee \013\010attacks have a 5% chance to \013\010trigger an extra attack on the \013\010target." } },
    { id = 110858, tree = 1, row = 5, col = 0, ranks = 2, name = "Improved Slam", icon = 132340, desc = { "Reduces the cooldown of your Slam ability by 2.5 sec, the cast time and global cooldown by 0.25 sec, and Slam no longer interrupts or delays your melee swing.", "Reduces the cooldown of your Slam ability by 5 sec, the cast time and global cooldown by 0.5 sec, and Slam no longer interrupts or delays your melee swing." }, note = "Slam stops delaying your swing and gets a shorter cooldown and cast. Without it Slam costs you white damage; with it Slam is a free extra attack between Mortal Strikes." },
    { id = 105942, tree = 1, row = 5, col = 2, ranks = 3, name = "Improved Hamstring", icon = 132316, desc = { "Gives your Hamstring ability a 5% chance to immobilize the target for 5 sec.", "Gives your Hamstring ability a 10% chance to immobilize the target for 5 sec.", "Gives your Hamstring ability a 15% chance to immobilize the target for 5 sec." } },
    { id = 105941, tree = 1, row = 6, col = 1, ranks = 1, name = "Mortal Strike", icon = 132355, requires = { 105945, 1 }, desc = { "A vicious strike that deals weapon damage plus 85 and wounds the target, reducing the effectiveness of any healing by 50% for 10 sec." } },
    { id = 105938, tree = 2, row = 0, col = 1, ranks = 5, name = "Booming Voice", icon = 136075, desc = { "Increases the area of effect of your Shouts by 10% and reduces the Rage cost by of your Shouts and Howls by 5%.", "Increases the area of effect of your Shouts by 20% and reduces the Rage cost by of your Shouts and Howls by 10%.", "Increases the area of effect of your Shouts by 30% and reduces the Rage cost by of your Shouts and Howls by 15%.", "Increases the area of effect of your Shouts by 40% and reduces the Rage cost by of your Shouts and Howls by 20%.", "Increases the area of effect of your Shouts by 50% and reduces the Rage cost by of your Shouts and Howls by 25%." }, note = "Shouts cost 25% less rage and reach 50% farther. Battle Shout is refreshed all fight, so the rage saved goes into attacks, and the whole group stays in range." },
    { id = 105939, tree = 2, row = 0, col = 2, ranks = 5, name = "Cruelty", icon = 132292, desc = { "Improves your chance to get a critical strike with melee attacks by 1%.", "Improves your chance to get a critical strike with melee attacks by 2%.", "Improves your chance to get a critical strike with melee attacks by 3%.", "Improves your chance to get a critical strike with melee attacks by 4%.", "Improves your chance to get a critical strike with melee attacks by 5%." } },
    { id = 110857, tree = 2, row = 1, col = 1, ranks = 5, name = "Lingering Rage", icon = 132356, desc = { "Increases the time before your Rage begins to decay after leaving combat by 2 sec.", "Increases the time before your Rage begins to decay after leaving combat by 4 sec.", "Increases the time before your Rage begins to decay after leaving combat by 6 sec.", "Increases the time before your Rage begins to decay after leaving combat by 8 sec.", "Increases the time before your Rage begins to decay after leaving combat by 10 sec." }, note = "Rage starts to fade 2 sec later per point after a fight: you walk into the next leveling pull with some of the last one's rage." },
    { id = 105937, tree = 2, row = 1, col = 2, ranks = 5, name = "Unbridled Wrath", icon = 136097, desc = { "Gives you a 12% chance to generate 1 additional Rage when you deal melee damage with a weapon.", "Gives you a 24% chance to generate 1 additional Rage when you deal melee damage with a weapon.", "Gives you a 36% chance to generate 1 additional Rage when you deal melee damage with a weapon.", "Gives you a 48% chance to generate 1 additional Rage when you deal melee damage with a weapon.", "Gives you a 60% chance to generate 1 additional Rage when you deal melee damage with a weapon." } },
    { id = 105953, tree = 2, row = 2, col = 0, ranks = 3, name = "Furious Precision", icon = 236309, desc = { "Increases your chance to hit with off-hand attacks by 4%.", "Increases your chance to hit with off-hand attacks by 7%.", "Increases your chance to hit with off-hand attacks by 10%." } },
    { id = 105935, tree = 2, row = 2, col = 1, ranks = 1, name = "Piercing Howl", icon = 136147, desc = { "Causes all enemies within 10 yds to be Dazed, reducing movement speed by 50% for 6 sec." } },
    { id = 105934, tree = 2, row = 2, col = 2, ranks = 3, name = "Blood Craze", icon = 136218, desc = { "Regenerates 1% of your total Health over 6 sec after being the victim of a critical strike or suffering more than 20% of your maximum Health from a single attack.", "Regenerates 2% of your total Health over 6 sec after being the victim of a critical strike or suffering more than 20% of your maximum Health from a single attack.", "Regenerates 3% of your total Health over 6 sec after being the victim of a critical strike or suffering more than 20% of your maximum Health from a single attack." } },
    { id = 105931, tree = 2, row = 2, col = 3, ranks = 5, name = "Enrage", icon = 136224, desc = { "Gives you a 30% chance to deal 2% increased Physical damage for 12 sec after being the victim of any damaging attack.", "Gives you a 30% chance to deal 4% increased Physical damage for 12 sec after being the victim of any damaging attack.", "Gives you a 30% chance to deal 6% increased Physical damage for 12 sec after being the victim of any damaging attack.", "Gives you a 30% chance to deal 8% increased Physical damage for 12 sec after being the victim of any damaging attack.", "Gives you a 30% chance to deal 10% increased Physical damage for 12 sec after being the victim of any damaging attack." } },
    { id = 105933, tree = 2, row = 3, col = 0, ranks = 5, name = "Dual Wield Specialization", icon = 132147, desc = { "Increases the damage done by your off-hand weapon by 5% and the Rage generated by your off-hand attacks by 10%.", "Increases the damage done by your off-hand weapon by 10% and the Rage generated by your off-hand attacks by 20%.", "Increases the damage done by your off-hand weapon by 15% and the Rage generated by your off-hand attacks by 30%.", "Increases the damage done by your off-hand weapon by 20% and the Rage generated by your off-hand attacks by 40%.", "Increases the damage done by your off-hand weapon by 25% and the Rage generated by your off-hand attacks by 50%." } },
    { id = 113636, tree = 2, row = 3, col = 1, ranks = 1, name = "Reckless Swings", icon = 132334, desc = { "Your next 4 melee attacks generate 5 additional Rage. Lasts 8 sec." }, note = "Your next 4 swings give 5 extra rage each (20 in all) for 8 sec. Rage is what limits a warrior, so that's more Mortal Strikes, Bloodthirsts and Heroic Strikes." },
    { id = 105932, tree = 2, row = 3, col = 3, ranks = 2, name = "Improved Execute", icon = 135358, desc = { "Reduces the Rage cost of your Execute ability by 3.", "Reduces the Rage cost of your Execute ability by 5." } },
    { id = 105978, tree = 2, row = 4, col = 0, ranks = 2, name = "Improved Berserker Rage", icon = 136009, desc = { "Your Berserker Rage ability will instantly generate 5 Rage and has a 50% chance to remove all movement impairing effects when activated.", "Your Berserker Rage ability will instantly generate 10 Rage and has a 100% chance to remove all movement impairing effects when activated." }, note = "Berserker Rage gives 10 rage instantly and frees you from slows: extra rage and mobility on a short cooldown." },
    { id = 105927, tree = 2, row = 4, col = 1, ranks = 1, name = "Death Wish", icon = 136146, desc = { "When activated, increases your Physical damage done by 20% and makes you immune to Fear effects, but increases all damage you take by 5%. Lasts 30 sec." }, note = "+20% physical damage for 30 sec (and immune to Fear). A big burst for the Execute phase or a hard pull." },
    { id = 113569, tree = 2, row = 4, col = 2, ranks = 2, name = "Gore Drinker", icon = 135727, requires = { 105934, 3 }, desc = { "Your Enrage, Berserker Rage, Bloodrage, Death Wish, Reckless Swings, and Bloodthirst abilities cause your next 3 melee attacks to restore 0.5% of your maximum Health.", "Your Enrage, Berserker Rage, Bloodrage, Death Wish, Reckless Swings, and Bloodthirst abilities cause your next 3 melee attacks to restore 1% of your maximum Health." } },
    { id = 105926, tree = 2, row = 4, col = 3, ranks = 2, name = "Improved Intercept", icon = 132307, desc = { "Reduces the cooldown of your Intercept ability by 5 sec.", "Reduces the cooldown of your Intercept ability by 10 sec." } },
    { id = 105977, tree = 2, row = 5, col = 0, ranks = 2, name = "Improved Whirlwind", icon = 132369, desc = { "Reduces the cooldown of your Whirlwind ability by 1 sec and increases the damage it deals to the closest enemy by 15%.", "Reduces the cooldown of your Whirlwind ability by 2 sec and increases the damage it deals to the closest enemy by 30%." }, note = "Whirlwind comes back 2 sec sooner and hits the closest enemy 30% harder, so it's a strong single-target attack too, not only for packs." },
    { id = 105928, tree = 2, row = 5, col = 2, ranks = 3, name = "Flurry", icon = 132152, desc = { "Increases your melee attack speed by 10% for your next 3 swings after dealing a melee critical strike.", "Increases your melee attack speed by 20% for your next 3 swings after dealing a melee critical strike.", "Increases your melee attack speed by 30% for your next 3 swings after dealing a melee critical strike." } },
    { id = 105930, tree = 2, row = 6, col = 1, ranks = 1, name = "Bloodthirst", icon = 136012, requires = { 105927, 1 }, desc = { "Instantly attack the target causing damage equal to 45% of your Attack Power plus 30 and increasing your movement speed by 10% for 10 sec." } },
    { id = 105974, tree = 3, row = 0, col = 0, ranks = 2, name = "Improved Bloodrage", icon = 132277, desc = { "Increases all the Rage generated by your Bloodrage ability by 25%.", "Increases all the Rage generated by your Bloodrage ability by 50%." }, note = "Bloodrage gives 50% more rage: a rage boost at the pull, which is when a tank needs threat most." },
    { id = 105976, tree = 3, row = 0, col = 1, ranks = 5, name = "Shield Specialization", icon = 134952, desc = { "Increases your chance to Block attacks with your shield by 1% and grants you a 20% chance to generate 5 Rage when you Block.", "Increases your chance to Block attacks with your shield by 2% and grants you a 40% chance to generate 5 Rage when you Block.", "Increases your chance to Block attacks with your shield by 3% and grants you a 60% chance to generate 5 Rage when you Block.", "Increases your chance to Block attacks with your shield by 4% and grants you a 80% chance to generate 5 Rage when you Block.", "Increases your chance to Block attacks with your shield by 5% and grants you a 100% chance to generate 5 Rage when you Block." }, note = "More block chance with a shield, and blocks give rage: both survival and threat." },
    { id = 113570, tree = 3, row = 0, col = 2, ranks = 5, name = "Iron Will", icon = 135995, desc = { "Reduces the duration of Stun and Fear effects inflicted on you by 3%.", "Reduces the duration of Stun and Fear effects inflicted on you by 6%.", "Reduces the duration of Stun and Fear effects inflicted on you by 9%.", "Reduces the duration of Stun and Fear effects inflicted on you by 12%.", "Reduces the duration of Stun and Fear effects inflicted on you by 15%." } },
    { id = 105975, tree = 3, row = 1, col = 0, ranks = 5, name = "Anticipation", icon = 136056, desc = { "Increases your Defense Skill by 4.", "Increases your Defense Skill by 8.", "Increases your Defense Skill by 12.", "Increases your Defense Skill by 16.", "Increases your Defense Skill by 20." }, note = "+Defense: fewer hits, crits and crushing blows land on you." },
    { id = 105969, tree = 3, row = 1, col = 2, ranks = 3, name = "Improved Revenge", icon = 132353, desc = { "Increases damage dealt by your Revenge ability by 20%.", "Increases damage dealt by your Revenge ability by 40%.", "Increases damage dealt by your Revenge ability by 60%." }, note = "Revenge does 60% more damage. It's cheap and comes up often while tanking (after a dodge, parry or block), so it's a strong threat button." },
    { id = 105972, tree = 3, row = 1, col = 3, ranks = 3, name = "Improved Thunder Clap", icon = 132326, desc = { "Reduces the Rage cost of your Thunder Clap ability by 2.", "Reduces the Rage cost of your Thunder Clap ability by 4.", "Reduces the Rage cost of your Thunder Clap ability by 6." } },
    { id = 105970, tree = 3, row = 2, col = 0, ranks = 1, name = "Last Stand", icon = 135871, desc = { "When activated, this ability temporarily grants you 30% of your maximum health for 20 sec. After the effect expires, the health is lost." }, note = "An emergency button: +30% of your health for 20 sec. Saves the raid when healers fall behind." },
    { id = 105971, tree = 3, row = 2, col = 1, ranks = 2, name = "Master of Defense", icon = 132359, requires = { 105976, 5 }, desc = { "Grants you a 50% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped.", "Grants you a 100% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped." }, note = "Every dodge or parry with a shield gives 5 rage. Tanks get rage from being hit; this adds rage even from hits that miss you, so you have more for threat." },
    { id = 105967, tree = 3, row = 2, col = 2, ranks = 3, name = "Improved Disarm", icon = 132343, desc = { "Reduces the cooldown of your Disarm ability by 7 secs.", "Reduces the cooldown of your Disarm ability by 13 secs.", "Reduces the cooldown of your Disarm ability by 20 secs." } },
    { id = 110856, tree = 3, row = 2, col = 3, ranks = 3, name = "Defiance", icon = 132347, desc = { "Increases all threat generated in Defensive stance by an additional 7% while a shield is equipped.", "Increases all threat generated in Defensive stance by an additional 13% while a shield is equipped.", "Increases all threat generated in Defensive stance by an additional 20% while a shield is equipped." }, note = "+20% threat in Defensive Stance with a shield, on top of the stance's own +80% (they multiply: 2.16 times the threat of your damage). Threat is a tank's real job." },
    { id = 105968, tree = 3, row = 3, col = 0, ranks = 3, name = "Improved Sunder Armor", icon = 132363, desc = { "Reduces the Rage cost of your Sunder Armor ability by 1.", "Reduces the Rage cost of your Sunder Armor ability by 2.", "Reduces the Rage cost of your Sunder Armor ability by 3." }, note = "Sunder Armor costs 3 less rage. Tanks press it a lot early in a fight (5 stacks for the raid, plus threat), so the rage saved goes into Shield Slam and Revenge." },
    { id = 105966, tree = 3, row = 3, col = 1, ranks = 1, name = "Vanguard", icon = 4667427, desc = { "Your Charge ability is now usable while in Defensive Stance." } },
    { id = 105963, tree = 3, row = 3, col = 2, ranks = 2, name = "Improved Shield Bash", icon = 132357, desc = { "Gives your Shield Bash ability a 50% chance to Silence the target for 3 sec.", "Gives your Shield Bash ability a 100% chance to Silence the target for 3 sec." } },
    { id = 105964, tree = 3, row = 4, col = 0, ranks = 2, name = "Improved Shield Wall", icon = 132362, desc = { "Reduces the cooldown of your Shield Wall ability by 5.5 min.", "Reduces the cooldown of your Shield Wall ability by 11 min." }, note = "Shield Wall's cooldown drops by 11 minutes, so you can use it on every hard boss instead of once a night." },
    { id = 105965, tree = 3, row = 4, col = 1, ranks = 1, name = "Concussion Blow", icon = 132325, desc = { "Stuns the target for 5 sec." }, note = "A 5-second stun: for emergencies, dangerous adds and interrupting casters that can't be kicked. No damage, so the numbers can't see it." },
    { id = 105961, tree = 3, row = 4, col = 2, ranks = 3, name = "Focused Rage", icon = 132345, desc = { "Reduces the Rage cost of your offensive abilities by 1.", "Reduces the Rage cost of your offensive abilities by 2.", "Reduces the Rage cost of your offensive abilities by 3." }, note = "Your attacks cost 3 less rage, so you can press more Shield Slams, Revenges and Sunders." },
    { id = 105962, tree = 3, row = 5, col = 2, ranks = 5, name = "Bastion", icon = 134950, desc = { "Increases all damage you deal by 2% while a shield is equipped.", "Increases all damage you deal by 4% while a shield is equipped.", "Increases all damage you deal by 6% while a shield is equipped.", "Increases all damage you deal by 8% while a shield is equipped.", "Increases all damage you deal by 10% while a shield is equipped." } },
    { id = 105959, tree = 3, row = 6, col = 1, ranks = 1, name = "Shield Slam", icon = 134951, requires = { 105965, 1 }, desc = { "Slam the target with your shield, causing 421 to 439 damage, increased by your Block Value, and has a 50% chance of dispelling 1 magic effect on the target. Causes a very high amount of threat." } },
